create table public.guest_daily_usage(day date primary key, requests integer not null check(requests between 0 and 1000)); alter table public.guest_daily_usage enable row level security; revoke all on public.guest_daily_usage from public,anon,authenticated; grant select,insert,update on public.guest_daily_usage to service_role;
create function public.reserve_guest_request() returns boolean language plpgsql security invoker set search_path='' as $$ declare n integer; begin insert into public.guest_daily_usage as u(day,requests) values ((now() at time zone 'UTC')::date,1) on conflict(day) do update set requests=u.requests+1 where u.requests<100 returning requests into n; return n is not null; end; $$;
revoke all on function public.reserve_guest_request() from public,anon,authenticated; grant execute on function public.reserve_guest_request() to service_role;